// ===== Sai Lan helpers (ชุดเดียวกันทุก workflow) =====
const ZONE = 'Asia/Bangkok';
const NOW = $now.setZone(ZONE);
const TODAY = NOW.toFormat('yyyy-MM-dd');
const TOMORROW = NOW.plus({ days: 1 }).toFormat('yyyy-MM-dd');
const TS = NOW.toISO();
const ACTIVE = ['Confirmed', 'Checked-in', 'Need Attention'];          // สถานะที่ "กินห้อง"
const STATUS_TH = { 'Confirmed': 'ยืนยันแล้ว', 'Checked-in': 'กำลังเข้าพัก', 'Need Attention': 'ต้องดูแลด่วน',
  'Checked-out': 'เช็กเอาต์แล้ว', 'Cancelled': 'ยกเลิกแล้ว', 'No-show': 'ไม่มาเข้าพัก' };
const HK_STATUS = ['Clean', 'Dirty', 'Cleaning', 'Out of Order'];
const HK_TH = { 'Clean': 'พร้อมเข้าพัก', 'Dirty': 'รอทำความสะอาด', 'Cleaning': 'กำลังทำความสะอาด', 'Out of Order': 'ปิดปรับปรุง' };

const num = (v, d = 0) => { const s = String(v ?? '').replace(/,/g, '').trim(); const n = Number(s); return s !== '' && Number.isFinite(n) ? n : d; };
const bool = (v, d = false) => { const s = String(v ?? '').trim().toUpperCase(); return s === '' ? d : ['TRUE', 'YES', 'Y', '1', 'ON'].includes(s); };
const list = (v) => String(v ?? '').split(/[\n,]+/).map((s) => s.trim()).filter(Boolean);
const clip = (v, n) => String(v ?? '').trim().slice(0, n);

// วันที่จากชีต → yyyy-MM-dd (รองรับเลข serial ของ Sheets และ d/m/yyyy แบบไทย)
const normDate = (v) => {
  const s = String(v ?? '').trim();
  if (!s) return '';
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  if (/^\d{5}(\.\d+)?$/.test(s)) return DateTime.fromISO('1899-12-30', { zone: ZONE }).plus({ days: Math.floor(Number(s)) }).toFormat('yyyy-MM-dd');
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) { let y = Number(m[3]); if (y > 2400) y -= 543; return `${y}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`; }
  return s;
};

// ผลลัพธ์ Sheets API values:batchGet → { Config:[{...}], Bookings:[...], ..., cfg:{key:value} }
function readSheets(resp) {
  const S = {};
  for (const vr of resp.valueRanges || []) {
    const name = String(vr.range || '').split('!')[0].replace(/^'(.*)'$/, '$1');
    const [head = [], ...rows] = vr.values || [];
    const keys = head.map((h) => String(h ?? '').trim());
    S[name] = rows.filter((r) => (r || []).some((c) => String(c ?? '').trim() !== '')).map((r) => {
      const o = {};
      keys.forEach((k, j) => { if (k) o[k] = r[j] == null ? '' : String(r[j]).trim(); });
      return o;
    });
  }
  for (const k of ['Config', 'Bookings', 'RoomTypes', 'Rooms', 'Offers', 'Promos', 'Messages', 'ActivityLog']) S[k] = S[k] || [];
  S.Bookings = S.Bookings.filter((b) => b.booking_id);
  for (const b of S.Bookings) { b.check_in = normDate(b.check_in); b.check_out = normDate(b.check_out); }
  S.RoomTypes = S.RoomTypes.filter((t) => t.room_type).sort((a, b) => num(a.sort_order, 99) - num(b.sort_order, 99));
  S.Rooms = S.Rooms.filter((r) => r.room_number).map((r) => ({ ...r, hk_status: HK_STATUS.includes(r.hk_status) ? r.hk_status : 'Clean' }));
  S.cfg = {};
  for (const r of S.Config) if (r.key) S.cfg[String(r.key).trim()] = r.value ?? '';
  return S;
}

const overlaps = (aIn, aOut, bIn, bOut) => aIn < bOut && bIn < aOut;   // คืนที่ทับกัน (วันเช็กเอาต์ไม่นับ)

// ห้องว่างแต่ละประเภทในช่วงวัน (ไม่นับห้อง Out of Order และหักการจองที่ยังไม่ได้ระบุเลขห้อง)
function availability(S, ci, co, exceptId = '') {
  const busy = S.Bookings.filter((b) => ACTIVE.includes(b.status) && b.booking_id !== exceptId
    && b.check_in && b.check_out && overlaps(ci, co, b.check_in, b.check_out));
  const busyRooms = new Set(busy.filter((b) => b.room_number).map((b) => String(b.room_number)));
  const out = {};
  for (const t of S.RoomTypes) {
    const units = S.Rooms.filter((r) => r.room_type === t.room_type && r.hk_status !== 'Out of Order');
    const free = units.filter((r) => !busyRooms.has(String(r.room_number)));
    const unassigned = busy.filter((b) => !b.room_number && b.room_type === t.room_type).length;
    out[t.room_type] = { total: units.length, free, available: Math.max(0, free.length - unassigned) };
  }
  return out;
}
// เลือกห้อง: ห้องว่างที่สะอาดก่อน → ห้องว่างที่รอทำความสะอาด → ห้องที่แขกเดิมจะเช็กเอาต์วันนี้
// ขอ "ชั้นสูง" → ชั้นสูงก่อน, ที่เหลือเรียงเลขห้อง
function pickRoom(free, requests = '', S = null) {
  const high = /ชั้นสูง/.test(requests);
  const occupied = new Set((S ? S.Bookings : []).filter((x) => ['Checked-in', 'Need Attention'].includes(x.status) && x.room_number)
    .map((x) => String(x.room_number)));
  const rank = (r) => (occupied.has(String(r.room_number)) ? 2 : r.hk_status === 'Clean' ? 0 : 1);
  return [...free].sort((a, b) => (rank(a) - rank(b))
    || (high ? num(b.floor) - num(a.floor) : 0)
    || String(a.room_number).localeCompare(String(b.room_number), 'en', { numeric: true }))[0];
}

// ราคาต่อคืน (คืนวันศุกร์-เสาร์ใช้ weekend_price ถ้ามี)
function quote(type, ci, co) {
  const nights = [];
  let d = DateTime.fromISO(ci, { zone: ZONE });
  const end = DateTime.fromISO(co, { zone: ZONE });
  while (d.isValid && end.isValid && d < end && nights.length < 60) {
    const weekend = d.weekday === 5 || d.weekday === 6;
    const price = weekend && num(type.weekend_price) > 0 ? num(type.weekend_price) : num(type.price);
    nights.push({ date: d.toFormat('yyyy-MM-dd'), price, weekend });
    d = d.plus({ days: 1 });
  }
  return { nights, subtotal: nights.reduce((s, n) => s + n.price, 0) };
}

// โค้ดส่วนลด: ดีลส่วนตัวจากชีต Offers (Workflow E) หรือโค้ดทั่วไปจากชีต Promos
function checkPromo(S, code, uid) {
  code = String(code ?? '').trim().toUpperCase();
  if (!code) return null;
  const o = S.Offers.find((x) => String(x.promo_code).toUpperCase() === code);
  if (o) {
    if (o.converted_booking_id) return { code, valid: false, message: 'โค้ดนี้ถูกใช้ไปแล้ว' };
    if (o.valid_until && normDate(o.valid_until) < TODAY) return { code, valid: false, message: 'โค้ดนี้หมดอายุแล้ว' };
    if (uid && o.line_user_id && o.line_user_id !== uid) return { code, valid: false, message: 'โค้ดนี้เป็นสิทธิ์เฉพาะบัญชี LINE ที่ได้รับดีล' };
    const pct = num(o.discount, 10);
    return { code, valid: true, percent: pct, kind: 'personal', label: `ดีลพิเศษสำหรับคุณ ลด ${pct}%` };
  }
  const p = S.Promos.find((x) => String(x.code).toUpperCase() === code);
  if (p) {
    if (!bool(p.active, true)) return { code, valid: false, message: 'โค้ดนี้ปิดใช้งานแล้ว' };
    if (p.valid_until && normDate(p.valid_until) < TODAY) return { code, valid: false, message: 'โค้ดนี้หมดอายุแล้ว' };
    const pct = num(p.discount_percent);
    return { code, valid: pct > 0, percent: pct, kind: 'general', label: p.note || `ส่วนลด ${pct}%`, message: pct > 0 ? '' : 'โค้ดนี้ไม่มีส่วนลด' };
  }
  return { code, valid: false, message: 'ไม่พบโค้ดส่วนลดนี้' };
}
const discountOf = (subtotal, promo) => (promo && promo.valid ? Math.round(subtotal * Math.min(100, Math.max(0, promo.percent)) / 100) : 0);
const freeCancelUntil = (S, ci) => DateTime.fromISO(ci, { zone: ZONE }).minus({ days: num(S.cfg.free_cancel_days, 1) }).toFormat('yyyy-MM-dd');
const thaiDate = (ymd, weekday = true) => {
  const d = DateTime.fromISO(String(ymd || ''), { zone: ZONE });
  return d.isValid ? d.setLocale('th-TH').toLocaleString(weekday ? { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' } : { day: 'numeric', month: 'short', year: 'numeric' }) : String(ymd || '-');
};
const baht = (n) => '฿' + Math.round(num(n)).toLocaleString('en-US');
const guestsText = (b) => `${num(b.adults, 1)} ผู้ใหญ่${num(b.children) ? ` · ${num(b.children)} เด็ก` : ''}`;
const roomTypeName = (S, rt) => (S.RoomTypes.find((t) => t.room_type === rt) || {}).name || rt;
const hotelName = (S) => S.cfg.hotel_name || 'Sai Lan Hotel';

// ---- Flex แจ้งกลุ่มแม่บ้าน ----
function kv(label, value, strong = true) {
  return { type: 'box', layout: 'baseline', spacing: 'sm', contents: [
    { type: 'text', text: label, size: 'sm', color: '#8A8578', flex: 3 },
    { type: 'text', text: String(value || '-'), size: 'sm', color: '#1F1F25', weight: strong ? 'bold' : 'regular', flex: 7, wrap: true },
  ] };
}
function hkFlex(S, kind, b, extra = {}) {
  const TITLES = {
    new: ['📋 การจองใหม่ · เตรียมห้อง', '#8A6A1F'],
    checkout: ['🧹 เช็กเอาต์แล้ว · ทำความสะอาด', '#B23A2E'],
    move: ['🔁 แขกย้ายห้อง · ห้องเดิมว่างแล้ว', '#B23A2E'],
    reassign: ['🔁 เปลี่ยนห้อง · เตรียมห้องใหม่', '#8A6A1F'],
    cancel: ['❌ ยกเลิกการจอง · ไม่ต้องเตรียมห้อง', '#5C5850'],
  };
  const prep = kind === 'new' || kind === 'reassign';
  const [title, color] = TITLES[kind] || TITLES.new;
  const room = String(extra.room || b.room_number || '');
  const rows = [kv('ห้อง', `${room || 'ยังไม่ระบุ'} · ${roomTypeName(S, b.room_type)}`)];
  if (kind === 'reassign' && extra.from) rows.push(kv('ห้องเดิม', `${extra.from} (ไม่ต้องเตรียมแล้ว)`, false));
  if (prep || kind === 'cancel') {
    rows.push(kv('เช็กอิน', `${thaiDate(b.check_in)} · ${S.cfg.checkin_time || '14:00'}`));
    rows.push(kv('เช็กเอาต์', thaiDate(b.check_out)));
  }
  if (prep) {
    rows.push(kv('ผู้เข้าพัก', guestsText(b)));
    if (b.arrival_time) rows.push(kv('เวลาถึง', b.arrival_time));
    if (b.special_requests) rows.push(kv('คำขอพิเศษ', b.special_requests));
    if (b.check_in === TODAY) rows.push({ type: 'text', text: '⚡ เข้าพักวันนี้ กรุณาเตรียมห้องด่วน', size: 'sm', color: '#B23A2E', weight: 'bold', wrap: true, margin: 'md' });
  }
  if (kind === 'checkout' || kind === 'move') {
    rows.push(kv('เวลา', `${NOW.toFormat('HH:mm')} น.`));
    rows.push(kv('แขกถัดไป', extra.next || 'ยังไม่มีการจอง', !!extra.next));
  }
  const buttons = [];
  if (room && kind !== 'cancel') {
    if (!prep) buttons.push({ type: 'button', style: 'secondary', height: 'sm',
      action: { type: 'postback', label: 'เริ่มทำความสะอาด', data: `action=hk_start&room=${encodeURIComponent(room)}`, displayText: `🧹 เริ่มทำความสะอาดห้อง ${room}` } });
    buttons.push({ type: 'button', style: 'primary', color: '#2E7D4F', height: 'sm',
      action: { type: 'postback', label: 'ห้องพร้อมแล้ว ✅', data: `action=hk_done&room=${encodeURIComponent(room)}`, displayText: `✅ ห้อง ${room} พร้อมแล้ว` } });
  }
  const bubble = {
    type: 'bubble', size: 'kilo',
    header: { type: 'box', layout: 'vertical', backgroundColor: color, paddingAll: '14px',
      contents: [{ type: 'text', text: title, color: '#FFFFFF', weight: 'bold', size: 'md', wrap: true }] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '14px', contents: rows },
  };
  if (buttons.length) bubble.footer = { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '12px', contents: buttons };
  return { type: 'flex', altText: `${title} ห้อง ${room || '-'}`, contents: bubble };
}
// แขกคนถัดไปของห้องนี้ (วันนี้หรือหลังจากนี้)
function nextArrival(S, room, exceptId = '') {
  const n = S.Bookings.filter((x) => String(x.room_number) === String(room) && x.booking_id !== exceptId
    && x.status === 'Confirmed' && x.check_in >= TODAY).sort((a, c) => a.check_in.localeCompare(c.check_in))[0];
  if (!n) return '';
  return n.check_in === TODAY ? `⚠️ วันนี้ ${S.cfg.checkin_time || '14:00'} (${n.booking_id})` : `${thaiDate(n.check_in)} (${n.booking_id})`;
}
// ===== จบ helpers =====

// ===== Split Events v2 (Run Once for All Items) =====
// 1 item ต่อ 1 event: { log, booking_update, config_update, room_update, activity, reply, pushes[] }
const events = $('LINE Webhook').first().json.body?.events || [];
const S = readSheets($input.first().json);
const cfg = S.cfg;
const HOTEL = hotelName(S);
const MENU = { 'การจองของฉัน': 'my_booking', 'แจ้งปัญหา': 'report_issue', 'ข้อมูลโรงแรม': 'hotel_info', 'ติดต่อพนักงาน': 'contact' };
const ISSUES = ['แอร์', 'เสียงดัง', 'ความสะอาด', 'อื่น ๆ'];
const ROLES = { staff: ['staff_group_id', 'กลุ่มพนักงานต้อนรับ (แจ้งปัญหาแขก)'], housekeeping: ['housekeeping_group_id', 'กลุ่มแม่บ้าน'] };

const byUser = (uid) => S.Bookings.filter((b) => b.line_user_id === uid);
const activeStay = (uid) => byUser(uid).filter((b) => ['Checked-in', 'Need Attention'].includes(b.status)).sort((a, b) => b.check_in.localeCompare(a.check_in))[0];
const currentOrNext = (uid) => byUser(uid).filter((b) => ACTIVE.includes(b.status) && b.check_out >= TODAY).sort((a, b) => a.check_in.localeCompare(b.check_in))[0];
const latest = (uid) => byUser(uid).sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)))[0];
const findBooking = (id) => S.Bookings.find((b) => b.booking_id === id);
const parseData = (s) => Object.fromEntries(String(s || '').split('&').filter(Boolean).map((p) => {
  const i = p.indexOf('='); const dec = (x) => { try { return decodeURIComponent(x); } catch { return x; } };
  return i < 0 ? [dec(p), ''] : [dec(p.slice(0, i)), dec(p.slice(i + 1))];
}));
const text = (t, quick) => { const m = { type: 'text', text: t }; if (quick) m.quickReply = { items: quick }; return m; };
const qr = (label, data, displayText) => ({ type: 'action', action: { type: 'postback', label, data, displayText: displayText || label } });
const issueQuick = (id) => ISSUES.map((c) => qr(c, `action=issue&booking_id=${encodeURIComponent(id)}&cat=${encodeURIComponent(c)}`, c));
const header = (title) => ({ type: 'box', layout: 'vertical', backgroundColor: '#16161A', paddingAll: '18px', contents: [
  { type: 'text', text: HOTEL, size: 'xs', color: '#D4AF6A', weight: 'bold' },
  { type: 'text', text: title, size: 'lg', color: '#FAF7F0', weight: 'bold', margin: 'sm', wrap: true } ] });
const canCancel = (b) => b.status === 'Confirmed' && TODAY <= freeCancelUntil(S, b.check_in);
const bookingUpdate = (b, changes) => ({ booking_id: b.booking_id, rating: b.rating, status: b.status, issue_category: b.issue_category,
  cancelled_at: b.cancelled_at, last_updated: TS, ...changes });

const couponFlex = (score) => ({
  type: 'flex', altText: `ขอบคุณสำหรับคะแนน ${score}/5 · รับเครื่องดื่มฟรี 1 แก้ว`,
  contents: { type: 'bubble', size: 'kilo', header: header('ขอบคุณสำหรับคะแนนค่ะ'),
    body: { type: 'box', layout: 'vertical', spacing: 'md', paddingAll: '18px', contents: [
      { type: 'text', text: '★'.repeat(score) + '☆'.repeat(5 - score), size: 'xl', color: '#D4AF6A', align: 'center' },
      { type: 'text', text: 'รับเครื่องดื่มฟรี 1 แก้ว ที่ Lobby Bar', size: 'sm', color: '#1F1F25', align: 'center', wrap: true },
      { type: 'box', layout: 'vertical', backgroundColor: '#FAF3E0', cornerRadius: 'md', paddingAll: '12px', contents: [
        { type: 'text', text: 'โค้ดคูปอง', size: 'xs', color: '#8A7A55', align: 'center' },
        { type: 'text', text: cfg.drink_coupon_code || 'WELCOME-DRINK', size: 'xl', weight: 'bold', color: '#8A6A1F', align: 'center', margin: 'xs' } ] },
      { type: 'text', text: 'แสดงข้อความนี้กับพนักงาน ใช้ได้ระหว่างการเข้าพักครั้งนี้', size: 'xxs', color: '#8A8578', align: 'center', wrap: true } ] } },
});

const bookingFlex = (b) => {
  const inHouse = ['Checked-in', 'Need Attention'].includes(b.status);
  const rows = [
    kv('หมายเลข', b.booking_id), kv('สถานะ', STATUS_TH[b.status] || b.status), kv('ผู้เข้าพัก', b.full_name),
    kv('ห้องพัก', roomTypeName(S, b.room_type) + (inHouse && b.room_number ? ` · ห้อง ${b.room_number}` : '')),
    kv('เช็กอิน', `${thaiDate(b.check_in)} · ${cfg.checkin_time || '14:00'}`),
    kv('เช็กเอาต์', `${thaiDate(b.check_out)} · ${cfg.checkout_time || '12:00'}`),
    kv('จำนวน', `${num(b.nights) || Math.round(DateTime.fromISO(b.check_out).diff(DateTime.fromISO(b.check_in), 'days').days)} คืน · ${guestsText(b)}`),
  ];
  if (b.special_requests) rows.push(kv('คำขอพิเศษ', b.special_requests, false));
  if (num(b.price_total)) rows.push(kv('ยอดชำระ', `${baht(b.price_total)}${b.payment_status === 'Paid' ? ' (ชำระแล้ว)' : ' · ชำระที่โรงแรม'}`));
  const bubble = { type: 'bubble', size: 'mega', header: header('การจองของคุณ'),
    body: { type: 'box', layout: 'vertical', spacing: 'md', paddingAll: '18px', contents: rows } };
  if (b.status === 'Confirmed') {
    bubble.footer = canCancel(b)
      ? { type: 'box', layout: 'vertical', paddingAll: '14px', contents: [
          { type: 'text', text: `ยกเลิกฟรีได้ถึง ${thaiDate(freeCancelUntil(S, b.check_in), false)}`, size: 'xxs', color: '#8A8578', align: 'center' },
          { type: 'button', style: 'secondary', height: 'sm', margin: 'sm',
            action: { type: 'postback', label: 'ยกเลิกการจอง', data: `action=cancel_ask&booking_id=${encodeURIComponent(b.booking_id)}`, displayText: 'ขอยกเลิกการจอง' } } ] }
      : { type: 'box', layout: 'vertical', paddingAll: '14px', contents: [
          { type: 'text', text: `เลยกำหนดยกเลิกฟรีแล้ว ต้องการเปลี่ยนแปลงโทร ${cfg.hotel_phone || 'หาโรงแรม'}`, size: 'xxs', color: '#8A8578', align: 'center', wrap: true } ] };
  }
  return { type: 'flex', altText: `การจองของคุณ ${b.booking_id}`, contents: bubble };
};

const roleFlex = (missing) => ({ type: 'flex', altText: 'ตั้งค่ากลุ่มนี้กับระบบโรงแรม', contents: { type: 'bubble', size: 'kilo',
  header: header('กลุ่มนี้ใช้ทำอะไรคะ?'),
  body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '16px', contents: [
    { type: 'text', text: 'เลือกหน้าที่ของกลุ่มนี้ ระบบจะส่งการแจ้งเตือนที่เกี่ยวข้องเข้ามาที่นี่', size: 'sm', color: '#5C5850', wrap: true },
    ...missing.map((role) => ({ type: 'button', style: 'primary', color: role === 'housekeeping' ? '#2E7D4F' : '#B08D3E', height: 'sm', margin: 'md',
      action: { type: 'postback', label: role === 'housekeeping' ? '🧹 กลุ่มแม่บ้าน' : '🛎️ กลุ่มพนักงาน',
        data: `action=set_group&role=${role}`, displayText: `ตั้งเป็น${ROLES[role][1]}` } })) ] } } });

const staffAlert = (b, cat) => [
  '🚨 แขกต้องการความช่วยเหลือ',
  `ห้อง: ${b.room_number || 'ยังไม่ระบุ'} (${roomTypeName(S, b.room_type)})`,
  `แขก: ${b.full_name}  โทร ${b.phone}`,
  `คะแนนคืนแรก: ${b.rating ? b.rating + '/5' : '— (แจ้งผ่านเมนู)'}`,
  `ปัญหา: ${cat}${cat === 'อื่น ๆ' ? ' (แขกจะพิมพ์รายละเอียดในแชท)' : ''}`,
  `Booking: ${b.booking_id}`,
  `เวลา: ${NOW.toFormat('dd/MM HH:mm')} น.`,
].join('\n');

const out = [];
for (const ev of events) {
  const src = ev.source || {};
  const uid = src.userId || '';
  const gid = src.groupId || '';
  const item = { event_type: ev.type, source_type: src.type || '', route: 'ignore', user_id: uid,
    log: null, booking_update: null, config_update: null, room_update: null, activity: null, reply: null, pushes: [] };
  const reply = (...messages) => { if (ev.replyToken) item.reply = { replyToken: ev.replyToken, messages: messages.slice(0, 5) }; };
  const activity = (action, b, room, detail, staff) => { item.activity = { timestamp: TS, staff, action, booking_id: b ? b.booking_id : '', room_number: room || (b ? b.room_number : ''), detail }; };

  // ---------- กลุ่ม LINE ----------
  if (src.type === 'group') {
    const roleOf = Object.keys(ROLES).filter((r) => cfg[ROLES[r][0]] === gid);
    if (ev.type === 'join') {
      const missing = Object.keys(ROLES).filter((r) => !cfg[ROLES[r][0]]);
      item.route = 'join';
      if (roleOf.length) reply(text(`กลุ่มนี้เป็น${roleOf.map((r) => ROLES[r][1]).join(' และ ')}อยู่แล้วค่ะ`));
      else if (missing.length) reply(roleFlex(missing));
      else reply(text('ระบบตั้งกลุ่มพนักงานและกลุ่มแม่บ้านครบแล้ว ถ้าต้องการเปลี่ยน ให้ลบค่า staff_group_id หรือ housekeeping_group_id ในชีต Config แล้วเชิญบอทเข้ากลุ่มใหม่'));
    } else if (ev.type === 'postback') {
      const d = parseData(ev.postback?.data);
      if (d.action === 'set_group' && ROLES[d.role]) {
        const [key, label] = ROLES[d.role];
        item.route = 'set_group';
        if (cfg[key] && cfg[key] !== gid) reply(text(`มี${label}อยู่แล้ว ถ้าต้องการเปลี่ยน ให้ลบค่า ${key} ในชีต Config ก่อน`));
        else if (cfg[key] === gid) reply(text(`กลุ่มนี้เป็น${label}อยู่แล้วค่ะ`));
        else {
          item.config_update = { key, value: gid };
          activity('set_group', null, '', `ตั้ง ${key}`, 'ระบบ');
          reply(text(d.role === 'housekeeping'
            ? '✅ ตั้งเป็นกลุ่มแม่บ้านแล้ว\nเมื่อมีการจองใหม่หรือแขกเช็กเอาต์ ระบบจะแจ้งเลขห้องเข้ามาที่นี่ กดปุ่มในข้อความเพื่ออัปเดตสถานะห้องได้เลย'
            : '✅ ตั้งเป็นกลุ่มพนักงานแล้ว\nเมื่อแขกแจ้งปัญหา ระบบจะแจ้งเตือนเข้ากลุ่มนี้'));
        }
      } else if (['hk_start', 'hk_done'].includes(d.action)) {
        item.route = d.action;
        const room = S.Rooms.find((r) => String(r.room_number) === String(d.room));
        if (!roleOf.length) reply(text('ปุ่มนี้ใช้ได้เฉพาะในกลุ่มแม่บ้านหรือกลุ่มพนักงานของโรงแรมค่ะ'));
        else if (!room) reply(text(`ไม่พบห้อง ${d.room} ในชีต Rooms`));
        else {
          const st = d.action === 'hk_done' ? 'Clean' : 'Cleaning';
          item.room_update = { room_number: room.room_number, hk_status: st, hk_note: st === 'Clean' ? '' : room.hk_note, hk_updated_at: TS, hk_updated_by: 'แม่บ้าน (LINE)' };
          activity(d.action, null, room.room_number, HK_TH[st], 'แม่บ้าน (LINE)');
          reply(text(st === 'Clean' ? `✅ ห้อง ${room.room_number} พร้อมเข้าพักแล้ว (${NOW.toFormat('HH:mm')} น.)` : `🧹 รับทราบ กำลังทำความสะอาดห้อง ${room.room_number}`));
        }
      }
    }
    // ข้อความคุยกันในกลุ่ม → ไม่บันทึก ไม่ตอบ
  }

  // ---------- ข้อความจากแขก (แชท 1:1) ----------
  else if (ev.type === 'message' && src.type === 'user') {
    const m = ev.message || {};
    const msgText = m.type === 'text' ? m.text : `[${m.type || 'unknown'}]`;
    const bk = activeStay(uid) || currentOrNext(uid) || latest(uid);
    item.route = 'message';
    item.log = { timestamp: TS, line_user_id: uid, booking_id: bk?.booking_id || '', direction: 'in', text: String(msgText).slice(0, 1000) };
    const cmd = m.type === 'text' ? MENU[m.text.trim()] : null;
    if (cmd === 'hotel_info') {
      item.route = 'menu_hotel_info';
      reply(text([`🏨 ${HOTEL}`, `เช็กอิน ${cfg.checkin_time || '14:00'} · เช็กเอาต์ ${cfg.checkout_time || '12:00'}`,
        cfg.breakfast_time && `🍳 อาหารเช้า ${cfg.breakfast_time}`, cfg.wifi_name && `📶 WiFi: ${cfg.wifi_name}`,
        cfg.wifi_password && `🔑 รหัสผ่าน: ${cfg.wifi_password}`, cfg.hotel_address && `📍 ${cfg.hotel_address}`,
        cfg.hotel_phone && `📞 ${cfg.hotel_phone}`].filter(Boolean).join('\n')));
    } else if (cmd === 'contact') {
      item.route = 'menu_contact';
      reply(text(`📞 ติดต่อพนักงานได้ที่ ${cfg.hotel_phone || '(ยังไม่ได้ตั้งค่าเบอร์)'} ตลอด 24 ชม.\nหรือพิมพ์ข้อความทิ้งไว้ในแชทนี้ พนักงานจะตอบกลับโดยเร็วค่ะ`));
    } else if (cmd === 'my_booking') {
      item.route = 'menu_my_booking';
      const b = currentOrNext(uid) || latest(uid);
      if (b) reply(bookingFlex(b));
      else reply(text(`ยังไม่พบการจองของคุณค่ะ${cfg.liff_url ? '\nจองห้องได้ที่ ' + cfg.liff_url : '\nกดเมนู "จองห้อง" ได้เลย'}`));
    } else if (cmd === 'report_issue') {
      item.route = 'menu_report_issue';
      const b = activeStay(uid);
      if (b) reply(text('เกิดปัญหาเรื่องใดคะ เลือกด้านล่างได้เลย พนักงานจะรีบไปดูแล', issueQuick(b.booking_id)));
      else reply(text('ไม่พบห้องที่คุณกำลังเข้าพักอยู่ค่ะ\nถ้าต้องการความช่วยเหลือ กดเมนู "ติดต่อพนักงาน" ได้เลย'));
    }
  }

  // ---------- postback จากแขก ----------
  else if (ev.type === 'postback' && src.type === 'user') {
    const d = parseData(ev.postback?.data);
    const b = d.booking_id ? findBooking(d.booking_id) : null;
    if (d.action === 'cancel_no') { item.route = 'cancel_no'; reply(text('ได้เลยค่ะ การจองของคุณยังคงอยู่ตามเดิม 😊')); }
    else if (!b || b.line_user_id !== uid) {
      item.route = 'postback_invalid';
      reply(text('ไม่พบการจองนี้ในระบบค่ะ ถ้าต้องการความช่วยเหลือ กดเมนู "ติดต่อพนักงาน"'));
    } else if (d.action === 'rate') {
      const score = Number(d.score);
      if (!Number.isInteger(score) || score < 1 || score > 5) item.route = 'postback_invalid';
      else if (b.rating) { item.route = 'rate_duplicate'; reply(text(`เราได้รับคะแนน ${b.rating}/5 ของคุณแล้ว ขอบคุณค่ะ 🙏`)); }
      else {
        item.booking_update = bookingUpdate(b, { rating: String(score) });
        if (score <= 3) {
          item.route = 'rate_low';
          reply(text('ขออภัยที่การเข้าพักยังไม่ดีเท่าที่ควรค่ะ 🙏\nช่วยบอกเราหน่อยว่าเกิดปัญหาเรื่องใด พนักงานจะรีบไปดูแลทันที', issueQuick(b.booking_id)));
        } else { item.route = 'rate_high'; reply(couponFlex(score)); }
        activity('rating', b, '', `ให้คะแนน ${score}/5`, 'แขก (LINE)');
      }
    } else if (d.action === 'issue') {
      const cat = ISSUES.includes(d.cat) ? d.cat : 'อื่น ๆ';
      if (b.status === 'Need Attention' && b.issue_category === cat) { item.route = 'issue_duplicate'; reply(text('พนักงานได้รับแจ้งเรื่องนี้แล้ว กำลังดำเนินการค่ะ 🙏')); }
      else if (!['Checked-in', 'Need Attention'].includes(b.status)) { item.route = 'issue_not_in_house'; reply(text('การจองนี้ไม่ได้อยู่ระหว่างเข้าพักค่ะ ถ้าต้องการความช่วยเหลือ กดเมนู "ติดต่อพนักงาน"')); }
      else {
        item.route = 'issue';
        item.booking_update = bookingUpdate(b, { status: 'Need Attention', issue_category: cat });
        activity('issue', b, '', `แจ้งปัญหา: ${cat}`, 'แขก (LINE)');
        reply(text(cat === 'อื่น ๆ' ? 'แจ้งพนักงานแล้วค่ะ 🙏 รบกวนพิมพ์รายละเอียดสั้น ๆ ในแชทนี้ได้เลย'
          : `แจ้งพนักงานเรื่อง "${cat}" แล้วค่ะ 🙏 พนักงานกำลังไปดูแลที่ห้องของคุณ`));
        if (cfg.staff_group_id) item.pushes.push({ to: cfg.staff_group_id, messages: [text(staffAlert(b, cat))] });
      }
    } else if (d.action === 'cancel_ask') {
      item.route = 'cancel_ask';
      if (!canCancel(b)) reply(text(b.status === 'Confirmed'
        ? `การจองนี้เลยกำหนดยกเลิกฟรีแล้วค่ะ ต้องการเปลี่ยนแปลงกรุณาโทร ${cfg.hotel_phone || 'หาโรงแรม'}`
        : `การจองนี้อยู่ในสถานะ "${STATUS_TH[b.status] || b.status}" ยกเลิกออนไลน์ไม่ได้ค่ะ`));
      else reply(text(`ยืนยันยกเลิกการจอง ${b.booking_id}\n${roomTypeName(S, b.room_type)} · ${thaiDate(b.check_in)} ใช่ไหมคะ?`, [
        qr('ยืนยันยกเลิก', `action=cancel_confirm&booking_id=${encodeURIComponent(b.booking_id)}`, 'ยืนยันยกเลิกการจอง'),
        qr('ไม่ยกเลิก', 'action=cancel_no', 'ไม่ยกเลิก')]));
    } else if (d.action === 'cancel_confirm') {
      item.route = 'cancel_confirm';
      if (!canCancel(b)) reply(text(b.status === 'Cancelled' ? 'การจองนี้ถูกยกเลิกไปแล้วค่ะ' : 'ไม่สามารถยกเลิกการจองนี้ออนไลน์ได้แล้วค่ะ กรุณาติดต่อโรงแรม'));
      else {
        item.booking_update = bookingUpdate(b, { status: 'Cancelled', cancelled_at: TS });
        activity('cancel', b, '', 'แขกยกเลิกผ่าน LINE', 'แขก (LINE)');
        reply(text(`ยกเลิกการจอง ${b.booking_id} เรียบร้อยแล้วค่ะ\nหวังว่าจะได้ต้อนรับคุณในโอกาสหน้านะคะ 🙏`));
        if (cfg.housekeeping_group_id && bool(cfg.hk_notify_new_booking, true) && b.room_number && b.check_in <= TOMORROW)
          item.pushes.push({ to: cfg.housekeeping_group_id, messages: [hkFlex(S, 'cancel', b)] });
      }
    }
  }

  if (item.route !== 'ignore') out.push({ json: item, pairedItem: { item: 0 } });
}
return out;
